                        config.isEnabled(),
                        this::appendPlatformData,
                        this::appendServiceData,
                        task -> server.getScheduler().buildTask(plugin, task).schedule(),
                        () -> true,
                        logger::warn,
                        logger::info,
                        config.isLogErrorsEnabled(),
